package com.Senai.Mubak.service; /** Utilitário de CPF/CNPJ: remove máscara e verifica se há 11 ou 14 dígitos. */ public final class DocumentoValidator {private DocumentoValidator(){} public static String digits(String v){return v==null?"":v.replaceAll("\\D","");} public static boolean valido(String v){String d=digits(v); return d.length()==11||d.length()==14;} }